use super::{
    authority::{self, Capture},
    *,
};
use crate::EngineEvent;
use engine_sequencer::EventCrossing;
use std::{collections::BTreeMap, sync::Arc};

const MAX_PLAYERS: usize = 32;
const MAX_PROJECT_EVENTS: usize = 4096;
#[derive(Clone, Debug)]
pub struct SequenceEvent {
    pub owner: Entity,
    pub crossing: EventCrossing,
}
/// Crossings generated by the most recent prepare/step/command. Cleared at each operation.
#[derive(Resource, Default)]
pub struct SequenceEvents(pub Vec<SequenceEvent>);
#[derive(Clone, Copy, Debug, Serialize)]
pub struct SequenceStatus {
    pub position: f64,
    pub state: State,
    pub speed: f64,
    pub cycle: i64,
}
struct BoundPlayer {
    config: SequencePlayer,
    targets: Vec<Entity>,
    player: Player,
    capture: Option<Capture>,
}
#[derive(Resource, Default)]
pub(super) struct Sequences {
    players: BTreeMap<Entity, BoundPlayer>,
}
impl Sequences {
    fn sync(&mut self, world: &mut World) -> Result<()> {
        let configs: Vec<_> = world
            .iter_entities()
            .filter_map(|e| e.get::<SequencePlayer>().map(|c| (e.id(), c.clone())))
            .collect();
        if configs.len() > MAX_PLAYERS {
            return Err(invalid("At most 32 authored sequence players"));
        }
        let retire: Vec<_> = self
            .players
            .keys()
            .filter(|owner| {
                !configs.iter().any(|(entity, config)| {
                    entity == *owner && &self.players[owner].config == config
                })
            })
            .copied()
            .collect();
        for owner in retire {
            if let Some(mut old) = self.players.remove(&owner) {
                if let Some(capture) = old.capture.take() {
                    capture.restore(world);
                }
            }
        }
        for (owner, config) in configs {
            let targets = authority::resolve(world, owner, &config)?;
            if let Some(old) = self.players.get(&owner) {
                if old.targets != targets {
                    return Err(invalid(
                        "Sequence binding identity changed; stop and reauthor binding",
                    ));
                }
                continue;
            }
            let timeline = Arc::new(config.timeline.compile(targets.len()).map_err(mapped)?);
            let mut player = Player::new(timeline);
            player.set_speed(config.speed).map_err(mapped)?;
            player.set_looping(config.looping);
            if config.autoplay {
                player.play();
            }
            self.players.insert(
                owner,
                BoundPlayer {
                    config,
                    targets,
                    player,
                    capture: None,
                },
            );
        }
        self.acquire(world)
    }
    fn acquire(&mut self, world: &World) -> Result<()> {
        let mut claims = BTreeSet::new();
        let mut cuts = false;
        for (owner, bound) in &self.players {
            if bound.player.state() == State::Stopped {
                continue;
            }
            if crate::networking::is_remote_replica(world, *owner) {
                return Err(invalid("Remote replica cannot own a sequence"));
            }
            for track in &bound.player.timeline().document().tracks {
                let (binding, property) = track.target();
                let entity = bound.targets[binding];
                if !claims.insert((entity, property)) {
                    return Err(invalid("Two sequences claim the same target property"));
                }
                authority::read(world, entity, property)?;
            }
            if !bound.player.timeline().document().camera_cuts.is_empty() {
                if cuts {
                    return Err(invalid("Only one sequence may own global camera cuts"));
                }
                cuts = true;
            }
            if let Some(capture) = &bound.capture {
                capture.validate(world)?;
            }
        }
        // All conflicts have been checked before acquiring baseline values.
        for bound in self.players.values_mut() {
            if bound.player.state() != State::Stopped && bound.capture.is_none() {
                bound.capture = Some(Capture::new(
                    world,
                    &bound.targets,
                    bound.player.timeline(),
                )?);
            }
        }
        Ok(())
    }
    fn apply(&mut self, world: &mut World) -> Result<()> {
        for bound in self.players.values_mut() {
            if let Some(capture) = &mut bound.capture {
                capture.apply(world, &bound.targets, &bound.player)?;
            }
        }
        Ok(())
    }
    fn reset(&mut self, world: &mut World) {
        for (_, mut bound) in std::mem::take(&mut self.players) {
            if let Some(capture) = bound.capture.take() {
                capture.restore(world);
            }
        }
    }
}
fn operate(
    world: &mut World,
    operation: impl FnOnce(&mut Sequences, &mut World) -> Result<Vec<SequenceEvent>>,
) -> Result<()> {
    let mut sequences = world.remove_resource::<Sequences>().unwrap_or_default();
    world.init_resource::<SequenceEvents>();
    world.resource_mut::<SequenceEvents>().0.clear();
    let result = operation(&mut sequences, world).and_then(|events| {
        if events.len() > MAX_PROJECT_EVENTS { return Err(invalid("Sequence event batch exceeds 4096 crossings")); }
        let queued = events.iter().map(|event| EngineEvent {
            name: "sequence.marker".into(), source: Some(event.owner), target: None,
            payload: json!({"id":event.crossing.marker.id,"time":event.crossing.marker.time,"direction":event.crossing.direction,"cycle":event.crossing.cycle}),
        }).collect();
        crate::emit_events(world, queued)?;
        world.resource_mut::<SequenceEvents>().0 = events;
        Ok(())
    });
    if result.is_err() {
        sequences.reset(world);
    }
    world.insert_resource(sequences);
    result
}
/// Hydrated authored players bind and apply time zero before first render extraction.
pub fn prepare(world: &mut World) -> Result<()> {
    operate(world, |sequences, world| {
        sequences.sync(world)?;
        sequences.apply(world)?;
        Ok(vec![])
    })
}
/// Called after simulation and before network snapshot/world transform refresh.
pub fn step(world: &mut World, dt: f32) -> Result<()> {
    operate(world, |sequences, world| {
        if !dt.is_finite() || dt < 0. {
            return Err(invalid("Sequence delta must be finite and nonnegative"));
        }
        sequences.sync(world)?;
        let mut events = Vec::new();
        for (owner, bound) in &mut sequences.players {
            events.extend(
                bound
                    .player
                    .advance(f64::from(dt))
                    .map_err(mapped)?
                    .into_iter()
                    .map(|crossing| SequenceEvent {
                        owner: *owner,
                        crossing,
                    }),
            );
            if events.len() > MAX_PROJECT_EVENTS {
                return Err(invalid("Sequence event batch exceeds 4096 crossings"));
            }
        }
        sequences.apply(world)?;
        Ok(events)
    })
}
/// Native controls act immediately. Call after Runtime::start/hydration. Failures cancel captures.
/// Stop restores baseline fields; seek acquires at the requested position and defaults to silent.
pub fn command(world: &mut World, owner: Entity, command: Command) -> Result<()> {
    operate(world, |sequences, world| {
        sequences.sync(world)?;
        let bound = sequences
            .players
            .get_mut(&owner)
            .ok_or_else(|| invalid("Entity has no SequencePlayer"))?;
        let mut crossings = Vec::new();
        match command {
            Command::Play => bound.player.play(),
            Command::Pause => bound.player.pause(),
            Command::Stop => {
                bound.player.stop();
                if let Some(capture) = bound.capture.take() {
                    capture.restore(world);
                }
            }
            Command::Seek { position, events } => {
                crossings = bound.player.seek(position, events).map_err(mapped)?
            }
            Command::Speed(speed) => bound.player.set_speed(speed).map_err(mapped)?,
        }
        sequences.acquire(world)?;
        sequences.apply(world)?;
        crate::refresh_world_transforms(world)?;
        Ok(crossings
            .into_iter()
            .map(|crossing| SequenceEvent { owner, crossing })
            .collect())
    })
}
pub fn status(world: &World, owner: Entity) -> Option<SequenceStatus> {
    let bound = world.get_resource::<Sequences>()?.players.get(&owner)?;
    Some(SequenceStatus {
        position: bound.player.position(),
        state: bound.player.state(),
        speed: bound.player.speed(),
        cycle: bound.player.cycle(),
    })
}
/// Cancel every scene-local capture before scene replacement or runtime shutdown.
pub fn reset(world: &mut World) {
    if let Some(mut sequences) = world.remove_resource::<Sequences>() {
        sequences.reset(world);
        world.insert_resource(sequences);
    }
    if let Some(mut events) = world.get_resource_mut::<SequenceEvents>() {
        events.0.clear();
    }
}
